#!/usr/bin/env python3
"""Line counts for hand-written ``python/xpict`` modules (largest first).

Skips schemars / ``make types`` outputs (files whose header says
``Auto-generated``). Prints a console table: lines, path, total.
"""

from __future__ import annotations

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
HOST = ROOT / "python" / "xpict"

# First-line / header markers written by ``scripts/generate_live_python.py``.
_GENERATED_MARKERS = (
    "# Auto-generated from Rust schemars",
    "# Auto-generated",
    "# autogenerated",
)


def _is_generated(path: Path) -> bool:
    try:
        head = path.read_text(encoding="utf-8", errors="replace").splitlines()[:8]
    except OSError:
        return False
    blob = "\n".join(head)
    return any(m in blob for m in _GENERATED_MARKERS)


def _line_count(path: Path) -> int:
    text = path.read_text(encoding="utf-8", errors="replace")
    if not text:
        return 0
    # Count newline-terminated lines; a final non-empty line without \\n counts.
    n = text.count("\n")
    if not text.endswith("\n"):
        n += 1
    return n


def main() -> int:
    if not HOST.is_dir():
        print(f"error: missing {HOST}", file=sys.stderr)
        return 1

    rows: list[tuple[int, str]] = []
    skipped = 0
    for path in sorted(HOST.rglob("*.py")):
        if path.name == "__pycache__" or "__pycache__" in path.parts:
            continue
        if _is_generated(path):
            skipped += 1
            continue
        rel = path.relative_to(ROOT).as_posix()
        rows.append((_line_count(path), rel))

    rows.sort(key=lambda r: (-r[0], r[1]))
    total = sum(n for n, _ in rows)
    width = max((len(rel) for _, rel in rows), default=10)
    print(f"{'lines':>6}  path")
    print(f"{'-----':>6}  {'-' * width}")
    for n, rel in rows:
        print(f"{n:>6}  {rel}")
    print(f"{'-----':>6}  {'-' * width}")
    print(f"{total:>6}  total ({len(rows)} files; {skipped} generated skipped)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
